// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by time.Now.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket holds up to Burst tokens and refills at Rate tokens per second.
// A Limiter must be constructed with NewLimiter; the zero value is invalid.
type Limiter struct {
	mu     sync.Mutex
	rate   float64   // tokens per second
	burst  float64   // bucket capacity
	tokens float64   // current tokens
	last   time.Time // last refill time
	clock  Clock
}

// ErrInvalidLimiter is returned by NewLimiter for invalid parameters.
var ErrInvalidLimiter = errors.New("ratelimit: rate and burst must be positive")

// NewLimiter creates a Limiter that refills at rate tokens per second with a
// capacity of burst tokens, starting full. rate and burst must be > 0.
func NewLimiter(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 || burst <= 0 {
		return nil, ErrInvalidLimiter
	}
	if clock == nil {
		clock = RealClock()
	}
	return &Limiter{
		rate:   rate,
		burst:  float64(burst),
		tokens: float64(burst),
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens may be consumed at time now, advancing the
// bucket state only on success.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.last = now
	}
	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Tokens returns the current number of available tokens (for observability).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	elapsed := l.clock.Now().Sub(l.last).Seconds()
	t := l.tokens + elapsed*l.rate
	if t > l.burst {
		t = l.burst
	}
	return t
}
